lemma addSubgroup_closure_le_of_invertible_relation {G R : Type*} {m n r : Type}
    [hn : Fintype n] [hm : Fintype m] [Fintype r] [DecidableEq m]
    [AddCommMonoid G] [CommRing R] [Module R G]  {g : m → G} {x : n → G} {A : Matrix r m R}
    {B : Matrix r n R} (hA : ∃ M : Matrix m r R, M * A = 1)
    (hg : ∀ i, ∑ j , (A i j) • (g j) = ∑ j , (B i j) • (x j)) :
      Submodule.span R (Set.range g) ≤ Submodule.span R (Set.range x)

lemma subgroup_closure_le_of_invertible_relation {G : Type*} {m n r : Type}
  [hn : Fintype n] [hm : Fintype m] [Fintype r] [DecidableEq m]
  [CommGroup G] {g : m → G} {x : n → G} {A : Matrix r m ℤ} {B : Matrix r n ℤ}
  (hA : ∃ M : Matrix m r ℤ, M * A = 1)
  (hg : ∀ i, ∏ j , (g j) ^ (A i j) = ∏ j, (x j) ^ (B i j)) :
    Subgroup.closure (Set.range g) ≤ Subgroup.closure (Set.range x)

lemma subgroup_closure_eq_classGroup_of_bound {m n r : Type} {D : ℝ} {b : ℕ}
    [hn : Fintype n] [hm : Fintype m] [Fintype r] [DecidableEq m]
    {g : m → Ideal Oκ} {g' : m → nonZeroDivisors (Ideal (Oκ))}
    {x : n → Ideal Oκ} {x' : n → nonZeroDivisors (Ideal (Oκ))}
    (hg' : ∀ i, ↑(g' i) = g i) (hx' : ∀ i, ↑(x' i) = x i)
    (hbg : isFactorBaseBound K D) (hB : D < b)
    (hg : {I : Ideal Oκ | 0 < I.absNorm ∧ I.IsPrime ∧ I.absNorm < b} ⊆ Set.range g)
    {A : Matrix r m ℕ} {B : Matrix r n ℕ}
    (hA : ∃ M : Matrix m r ℤ, M * A.map (algebraMap ℕ ℤ) = 1)
    (hgmul : ∀ i, ∃ (α β : Oκ), ∃ (_ : α ≠ 0), ∃ (_ : β ≠ 0),
      Ideal.span {α} * ∏ j , (g j) ^ (A i j) = Ideal.span {β} * ∏ j, (x j) ^ (B i j)) :
      Subgroup.closure (Set.range (fun i => ClassGroup.mk0 (x' i))) = ⊤

lemma subgroup_closure_eq_classGroup_bound' {m n : Type} {D : ℝ} {b : ℕ}
    [hn : Fintype n] [hm : Fintype m] [DecidableEq m]
    {g : m → Ideal Oκ} {g' : m → nonZeroDivisors (Ideal (Oκ))}
    {x : n → Ideal Oκ} {x' : n → nonZeroDivisors (Ideal (Oκ))}
    (hg' : ∀ i, ↑(g' i) = g i) (hx' : ∀ i, ↑(x' i) = x i)
    (hbg : isFactorBaseBound K D) (hB : D < b)
    (hg : {I : Ideal Oκ | 0 < I.absNorm ∧ I.IsPrime ∧ I.absNorm < b} ⊆ Set.range g)
    (B : Matrix m n ℕ) (hgmul : ∀ i, ∃ (α β : Oκ), ∃ (_ : α ≠ 0), ∃ (_ : β ≠ 0),
      Ideal.span {α} * (g i) = Ideal.span {β} * ∏ j, (x j) ^ (B i j)) :
      Subgroup.closure (Set.range (fun i => ClassGroup.mk0 (x' i))) = ⊤

lemma subgroup_closure_eq_classGroup' {m n : Type} {D : ℝ} {b : ℕ}
    [hn : Fintype n] [hm : Fintype m] [DecidableEq m] {S : Type*}
    [CommRing S] [Nontrivial S] [IsDedekindDomain S] [Module.Free ℤ S]
    ( φ : S ≃+* Oκ)
    {g : m → Ideal S} {g' : m → nonZeroDivisors (Ideal (S))}
    {x : n → Ideal S} {x' : n → nonZeroDivisors (Ideal (S))}
    (hg' : ∀ i, ↑(g' i) = g i) (hx' : ∀ i, ↑(x' i) = x i)
    (hbg : isFactorBaseBound K D) (hB : D < b)
    (hg : {I : Ideal S | 0 < I.absNorm ∧ I.IsPrime ∧ I.absNorm < b} ⊆ Set.range g)
    (B : Matrix m n ℕ) (hgmul : ∀ i, ∃ (α β : S), ∃ (_ : α ≠ 0), ∃ (_ : β ≠ 0),
      Ideal.span {α} * (g i) = Ideal.span {β} * ∏ j, (x j) ^ (B i j)) :
      Subgroup.closure (Set.range (fun i => ClassGroup.mk0 (x' i))) = ⊤

protected lemma coord_bit0 (t : TimesTable ι R S) (k : ι) {e₁ : S} {e₁' e' : R}
